<?php
// Expense records are separate from kimchi order imports.
db()->exec("CREATE TABLE IF NOT EXISTS expense_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE, capital TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
db()->exec("CREATE TABLE IF NOT EXISTS expenses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_key CHAR(32) NOT NULL UNIQUE,expense_date DATE NOT NULL,vendor VARCHAR(150) NOT NULL,category_id INT UNSIGNED NOT NULL,description TEXT NOT NULL,subtotal_cents INT UNSIGNED NOT NULL,hst_cents INT UNSIGNED NOT NULL DEFAULT 0,other_tax_cents INT UNSIGNED NOT NULL DEFAULT 0,total_cents INT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'CAD',business_pct DECIMAL(5,2) NOT NULL DEFAULT 100,itc_status VARCHAR(12) NOT NULL DEFAULT 'review',deductible_pct DECIMAL(5,2) NOT NULL DEFAULT 100,payment_method VARCHAR(30) NOT NULL DEFAULT '',ocr_text TEXT NOT NULL,voided TINYINT NOT NULL DEFAULT 0,version INT UNSIGNED NOT NULL DEFAULT 1,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(expense_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
db()->exec("CREATE TABLE IF NOT EXISTS expense_receipts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,expense_id INT UNSIGNED NOT NULL,storage_key VARCHAR(80) NOT NULL UNIQUE,mime VARCHAR(50) NOT NULL,original_name VARCHAR(200) NOT NULL,sha256 CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(expense_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
db()->exec("CREATE TABLE IF NOT EXISTS expense_events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,expense_id INT UNSIGNED NOT NULL,actor_id INT UNSIGNED NOT NULL,detail LONGTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
db()->exec("CREATE TABLE IF NOT EXISTS expense_splits (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,expense_id INT UNSIGNED NOT NULL,category_id INT UNSIGNED NOT NULL,net_cents INT UNSIGNED NOT NULL,INDEX(expense_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
db()->exec("CREATE TABLE IF NOT EXISTS expense_import_batches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,year INT NOT NULL UNIQUE,source_sha CHAR(64) NOT NULL,filename VARCHAR(200) NOT NULL,summary LONGTEXT NOT NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
db()->exec("CREATE TABLE IF NOT EXISTS expense_import_rows (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id INT UNSIGNED NOT NULL,source_ref VARCHAR(100) NOT NULL,expense_id INT UNSIGNED NULL,state VARCHAR(12) NOT NULL,snapshot LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$version='20261115_expenses';
if(!query('SELECT version FROM schema_migrations WHERE version=?',[$version])->fetch()){
// Preserve the spreadsheet's categories, including categories absent from the first draft.
foreach(['Material'=>'재료 구입','Wages'=>'인건비','Advertising'=>'광고','Bank'=>'은행 수수료','Insurance'=>'보험','Meals'=>'식사·접대','Supplies'=>'소모품','Licenses'=>'허가·면허','Professional'=>'전문가 수수료','Rent'=>'임대료','Phone/Internet'=>'전화·인터넷','Maintenance'=>'수리·유지','Utilities'=>'수도·전기·가스','Auto'=>'차량','Lease'=>'리스','Fixed Assets'=>'장비·자산 구입','Others'=>'기타·분류 확인'] as $english=>$korean)query('INSERT INTO expense_categories (name,capital) VALUES (?,?) ON DUPLICATE KEY UPDATE id=id',[$korean,$english==='Fixed Assets'?1:0]);
query('INSERT INTO schema_migrations (version) VALUES (?)',[$version]);
}
require __DIR__.'/bookkeeping.php';
